using Leaderboard.Api.Contracts;
using Leaderboard.Api.Domain;
using Leaderboard.Api.Options;
using Microsoft.Extensions.Options;

namespace Leaderboard.Api.Endpoints;

/// <summary>Endpoints de /api/scores. Ver docs/tasks/NET-501.md.</summary>
public static class ScoreEndpoints
{
    /// <summary>Registra los endpoints.</summary>
    public static IEndpointRouteBuilder MapScoreEndpoints(this IEndpointRouteBuilder app)
    {
        app.MapPost("/api/scores", async (SubmitScoreRequest request, IScoreRepository repo, IOptions<LeaderboardOptions> options, CancellationToken ct) =>
        {
            var limits = options.Value;
            var errors = new Dictionary<string, string[]>();

            if (!IsValidPlayerId(request.PlayerId, limits.MaxPlayerIdLength))
            {
                errors["playerId"] = ["playerId debe tener 1 a MaxPlayerIdLength caracteres: letras, números, '_' o '-'."];
            }

            if (request.Score is null || request.Score < 0 || request.Score > limits.MaxScore)
            {
                errors["score"] = ["score debe ser un entero entre 0 y MaxScore."];
            }

            if (errors.Count > 0)
            {
                return Results.ValidationProblem(errors);
            }

            var entry = await repo.SubmitAsync(request.PlayerId!, request.Score!.Value, ct);
            var response = Rank(await repo.GetAllAsync(ct)).First(r => r.PlayerId == entry.PlayerId);
            return Results.Created($"/api/scores/{response.PlayerId}", response);
        });

        app.MapGet("/api/scores", async (int? top, IScoreRepository repo, IOptions<LeaderboardOptions> options, CancellationToken ct) =>
        {
            var limits = options.Value;
            if (top is < 1)
            {
                return Results.ValidationProblem(new Dictionary<string, string[]>
                {
                    ["top"] = ["top debe ser al menos 1."],
                });
            }

            var count = Math.Min(top ?? limits.DefaultTop, limits.MaxTop);
            var ranked = Rank(await repo.GetAllAsync(ct));
            return Results.Ok(ranked.Take(count));
        });

        return app;
    }

    /// <summary>Valida el largo y los caracteres permitidos de playerId.</summary>
    private static bool IsValidPlayerId(string? playerId, int maxLength) =>
        !string.IsNullOrEmpty(playerId) && playerId.Length <= maxLength && playerId.All(IsAllowedPlayerIdChar);

    private static bool IsAllowedPlayerIdChar(char c) => char.IsAsciiLetterOrDigit(c) || c is '_' or '-';

    /// <summary>Ordena por puntaje descendente; en empate gana quien lo logró antes.</summary>
    private static List<ScoreResponse> Rank(IEnumerable<ScoreEntry> entries) =>
        entries.OrderByDescending(e => e.Score)
            .ThenBy(e => e.Sequence)
            .Select((e, i) => new ScoreResponse(e.PlayerId, e.Score, i + 1))
            .ToList();
}

