using Leaderboard.Api.Domain;

namespace Leaderboard.Api.Infrastructure;

/// <summary>Repositorio en memoria. Seguro para peticiones concurrentes.</summary>
public sealed class InMemoryScoreRepository : IScoreRepository
{
    private readonly Dictionary<string, ScoreEntry> _entries = new();
    private readonly object _gate = new();
    private long _sequence;

    /// <inheritdoc />
    public Task<ScoreEntry> SubmitAsync(string playerId, int score, CancellationToken cancellationToken)
    {
        lock (_gate)
        {
            if (_entries.TryGetValue(playerId, out var current) && score <= current.Score)
            {
                return Task.FromResult(current);
            }

            _sequence++;
            var entry = new ScoreEntry(playerId, score, _sequence);
            _entries[playerId] = entry;
            return Task.FromResult(entry);
        }
    }

    /// <inheritdoc />
    public Task<IReadOnlyList<ScoreEntry>> GetAllAsync(CancellationToken cancellationToken)
    {
        lock (_gate)
        {
            return Task.FromResult<IReadOnlyList<ScoreEntry>>(_entries.Values.ToList());
        }
    }

    /// <inheritdoc />
    public Task<ScoreEntry?> FindAsync(string playerId, CancellationToken cancellationToken)
    {
        lock (_gate)
        {
            return Task.FromResult(_entries.TryGetValue(playerId, out var e) ? e : null);
        }
    }
}
